                          && (&dut.g_row[y].g_col[x].u_tile.u_router.g_port[p].u_in.empty)
                          && !dut.g_row[y].g_col[x].u_tile.u_router.g_port[p].u_in.sa_vld_q
                          && !dut.g_row[y].g_col[x].u_tile.u_router.g_port[p].u_out.link_vld_q;
