          end
          k = r * rchk_pkg::NRES + 8;
          chk.obs_fl[k] = ej_mon[r];
          chk.obs_v[k]  = ej_mon[r].vld && ej_mon[r].byp;
          for (int p = 0; p < 4; p++) begin
            k = r * rchk_pkg::NRES + 9 + p;
            chk.obs_cx[k] = o_cx[r][p];
            chk.obs_v[k]  = o_cx[r][p].vld;
          end
          chk.nck.p_res[r]  = p_res[r];
          chk.nck.p_fill[r] = p_fill[r];
          chk.nck.p_occ[r]  = EJ_DEPTH - int'(ej_free[r]);
          chk.nck.taken[r]  = longint'(v_btake[r]);
        end
        if (TWO) begin
          for (int r = 0; r < NN; r++) begin
            smo.tx_go[r]    = p_txgo[r];
            smo.tx_dst[r]   = int'(p_txdst[r]);
            smo.tx_mode[r]  = p_txmd[r];
            smo.dec[r]      = p_dec[r];
            smo.dec_s0[r]   = p_ds0[r];
            smo.dec_loc[r]  = p_dloc[r];
            smo.dec_src[r]  = int'(p_dsrc[r]);
            smo.dec_mode[r] = p_dmd[r];
            smo.dec_hops[r] = int'(p_dhops[r]);
            mck.st[r]       = p_st[r];
            for (int p = 0; p < 4; p++) begin
              mck.fl_v[r * 4 + p]   = o_flit[r][p].vld && o_flit[r][p].byp;
              mck.la_v[r * 4 + p]   = o_la[r][p].vld;
              mck.la_len[r * 4 + p] = int'(o_la[r][p].len);
              mck.cx_v[r * 4 + p]   = o_cx[r][p].vld;
            end
            mck.ej_v[r]    = ej_mon[r].vld && ej_mon[r].byp;
            mck.lal_v[r]   = p_lal[r].vld;
            mck.lal_len[r] = int'(p_lal[r].len);
          end
        end
        chk.step(int'(cyc));
        if (TWO) begin
          smo.step(int'(cyc));
          mck.step(int'(cyc));
        end
      end
    end
  end

  if (DESIGN == DESIGN_D) begin : g_cchk
    cchk_pkg::cchk cck;

    initial begin
      cck = new(MESH_N, REGION_N, NUM_VC, EPOCH, sched_pkg::A_DELAY, K_INIT, K_LO, K_HI);
      cchk_pkg::the_cchk = cck;
    end

    always @(posedge clk) begin
      if (rst_n && !cck.started) begin
        cck.c0      = longint'(cyc);
        cck.started = 1'b1;
      end
    end

    always @(negedge clk) begin
      if (cck.started) begin
        for (int r = 0; r < NN; r++) begin
          for (int p = 0; p < NPORTS; p++) begin
            cck.fl[r * NPORTS + p] = p_rin[r][p];
            cck.cr[r * NPORTS + p] = p_rcr[r][p];
          end
          cck.rcl[r] = int'(p_cl[r]);
          cck.rcg[r] = int'(p_cg[r]);
          cck.rpl[r] = int'(p_plan[r]);
        end
        cck.rsl  = longint'(p_sl);
        cck.rsg  = longint'(p_sg);
        cck.rkc  = int'(p_kc);
        cck.pol  = int'(ctrl_pol);
        cck.damp = ctrl_damp;
        cck.step(longint'(cyc));
      end
    end
  end

  if (DESIGN == DESIGN_C && SHADOW != 0) begin : g_shadow
    logic            s_inj_ready [NN], s_ej_valid [NN];
    flit_t           s_ej_flit   [NN], s_ej_mon   [NN];
    logic  [EFW-1:0] s_ej_free   [NN];
    flit_t [3:0]     s_flit [NN];
    la_t   [3:0]     s_la   [NN];
    cx_t   [3:0]     s_cx   [NN];

    mesh_top #(
      .MESH_N   (MESH_N),
      .NUM_VC   (NUM_VC),
      .VC_DEPTH (VC_DEPTH),
      .ALGO     (ALGO),
      .DESIGN   (DESIGN_B),
      .EJ_DEPTH (EJ_DEPTH),
      .B_MAX    (B_MAX),
      .T_MODE   (T_MODE)
    ) u_shadow (
      .clk_i       (clk),
      .rst_ni      (rst_n),
      .plan_i      (plan),
      .ctrl_pol_i  (1'b0),
      .ctrl_damp_i (1'b0),
      .inj_valid_i (inj_valid),
      .inj_ready_o (s_inj_ready),
      .inj_flit_i  (inj_flit),
      .ej_valid_o  (s_ej_valid),
      .ej_ready_i  (ej_ready),
      .ej_flit_o   (s_ej_flit),
      .ej_free_o   (s_ej_free),
      .ej_mon_o    (s_ej_mon)
    );

    for (genvar y = 0; y < MESH_N; y++) begin : g_sy
      for (genvar x = 0; x < MESH_N; x++) begin : g_sx
        assign s_flit[y * MESH_N + x] = u_shadow.g_row[y].g_col[x].u_tile.out_flit_o;
        assign s_la[y * MESH_N + x]   = u_shadow.g_row[y].g_col[x].u_tile.out_la_o;
        assign s_cx[y * MESH_N + x]   = u_shadow.g_row[y].g_col[x].u_tile.out_cx_o;
        always @(negedge clk) u_shadow.g_row[y].g_col[x].u_tile.u_router.tb_hold = hold_req[y * MESH_N + x];
      end
    end

    logic sh_on = 1'b0;
    always @(posedge clk) sh_on <= rst_n;

    always @(negedge clk) begin
      int    bad;
      string what;
      if (sh_on && !sh_diff) begin
        bad  = -1;
        what = "";
        for (int r = 0; r < NN; r++) begin
          if (bad < 0) begin
            if (s_inj_ready[r] != inj_ready[r] || s_ej_valid[r] != ej_valid[r] || s_ej_free[r] != ej_free[r]) begin
              bad  = r;
              what = $sformatf("NI handshake: inj_ready %0d/%0d ej_valid %0d/%0d ej_free %0d/%0d", inj_ready[r],
                               s_inj_ready[r], ej_valid[r], s_ej_valid[r], ej_free[r], s_ej_free[r]);
            end else if (s_ej_flit[r] != ej_flit[r] || s_ej_mon[r] != ej_mon[r]) begin
              bad  = r;
              what = "ejected flit or the NI's input link";
            end else if (s_flit[r] != o_flit[r]) begin
              bad  = r;
              what = "an output link's flit";
            end else if (s_la[r] != o_la[r]) begin
              bad  = r;
              what = "an output lookahead link";
            end else if (s_cx[r] != o_cx[r]) begin
              bad  = r;
              what = "an output cancel link";
            end
          end
        end
        `TB_CHECK(bad < 0, ("TL05: at cycle %0d design C and design B differ at R%0d: %s", cyc, bad, what))
        if (bad >= 0) sh_diff = 1'b1;
        else          sh_same++;
      end
    end
  end

  longint unsigned pp_cyc = 0, pp_kl = 0, pp_loc = 0;
  always @(posedge clk) begin : b_pp
    longint unsigned kk, ll;
    kk = longint'(p_st[0].kl);
    ll = longint'(p_st[0].loc);
    if (rst_n) begin
      pp_cyc <= pp_cyc + 1;
      pp_kl  <= pp_kl + kk;
      pp_loc <= pp_loc + ll;
    end
  end

  function automatic longint unsigned sum_sent();
    longint unsigned s = 0;
    for (int i = 0; i < NN; i++) s += v_sent[i];
    return s;
  endfunction

  function automatic longint unsigned sum_taken();
    longint unsigned s = 0;
    for (int i = 0; i < NN; i++) s += v_taken[i];
    return s;
  endfunction

  function automatic longint unsigned sum_heads();
    longint unsigned s = 0;
    for (int i = 0; i < NN; i++) s += v_heads[i];
    return s;
  endfunction

  function automatic longint unsigned sum_pkts();
    longint unsigned s = 0;
    for (int i = 0; i < NN; i++) s += v_pkts[i];
    return s;
  endfunction

  function automatic longint unsigned sum_blocked();
    longint unsigned s = 0;
    for (int i = 0; i < NN; i++) s += v_blocked[i];
    return s;
  endfunction

  function automatic longint unsigned sum_stall();
    longint unsigned s = 0;
    for (int i = 0; i < NN; i++) s += v_stall[i];
    return s;
  endfunction

  function automatic longint unsigned sum_inter();
    longint unsigned s = 0;
    for (int i = 0; i < NN; i++) s += v_inter[i];
    return s;
  endfunction

  function automatic longint unsigned max_fifo();
    longint unsigned m = 0;
    for (int i = 0; i < NN; i++) if (v_fifo[i] > m) m = v_fifo[i];
    return m;
  endfunction

  function automatic perf_pkg::snap_t perf_snap();
    perf_pkg::snap_t z;
    z.turns  = sum_of(v_turns);
    z.used   = sum_of(v_used);
    z.cxl    = sum_of(v_cxl);
    z.lost   = sum_of(v_lost);
    z.bflits = sum_of(v_bflits);
    z.bpkts  = sum_of(v_bpkts);
    z.dec    = sum_of(v_dec);
    z.acc    = sum_of(v_acc);
    z.rcx    = sum_of(v_rcx);
    z.nosh   = sum_of(v_nosh);
    z.two    = sum_of(v_two);
    return z;
  endfunction

  function automatic bit nodes_idle();
    for (int i = 0; i < NN; i++) begin
      if (v_queued[i] != 0 || !v_sink_ok[i] || int'(ej_free[i]) != EJ_DEPTH) return 1'b0;
    end
    return 1'b1;
  endfunction

  task automatic check_idle(string when);
    repeat (12) @(posedge clk);
    `TB_CHECK(&tile_idle, ("%s: mesh not idle afterwards, busy tiles %b", when, ~tile_idle))
    `TB_CHECK(nodes_idle(), ("%s: a source queue, sink or NI ejection FIFO still holds a packet", when))
    `TB_CHECK(sb_pkg::outstanding() == 0,
              ("%s: %0d packets created but not delivered", when, sb_pkg::outstanding()))
    if (rchk_pkg::the_chk != null) begin
      `TB_CHECK(rchk_pkg::the_chk.idle(), ("%s: the bypass checker still expects flits", when))
    end
  endtask

  function automatic void traffic_defaults();
    traffic_pkg::mesh_n       = MESH_N;
    traffic_pkg::pattern      = PAT_UNIFORM;
    traffic_pkg::rate         = 0.0;
    traffic_pkg::p_data       = 1.0 / 3.0;
    traffic_pkg::hot_node     = -1;
    traffic_pkg::hot_frac     = 0.2;
    traffic_pkg::region_n     = TWO ? REGION_N : 0;
    traffic_pkg::p_local      = 0.5;
    traffic_pkg::phase_a      = PAT_UNIFORM;
    traffic_pkg::phase_b      = PAT_TRANSPOSE;
    traffic_pkg::phase_len    = 500;
    traffic_pkg::gen_on       = 1'b0;
    traffic_pkg::period       = 0;
    traffic_pkg::per_t0       = 0;
    traffic_pkg::sink_stall_p = 0.0;
    traffic_pkg::fs_node      = FS_NONE;
    traffic_pkg::fs_start     = 0;
    traffic_pkg::fs_end       = 0;
  endfunction

  function automatic string algo_name();
    if (ALGO == RT_XY) return "XY";
    return "adaptive";
  endfunction

  function automatic string tmode_name();
    string m;
    if (T_MODE == sched_pkg::TM_TIGHT) m = "TIGHT";
    else                               m = "SAFE";
    return m;
  endfunction

  function automatic string design_name();
    string s, m;
    m = tmode_name();
    if (DESIGN == DESIGN_A)      s = "design A";
    else if (DESIGN == DESIGN_B) s = $sformatf("design B, B_MAX %0d, %s subslots of %0d cycles", B_MAX, m,
                                               sched_pkg::t_sub(MESH_N, B_MAX, T_MODE));
    else if (DESIGN == DESIGN_D) s = $sformatf("design D, %0dx%0d regions, k_L %0d from reset and by demand every epoch of %0d, B_MAX %0d, %s subslots of %0d (local %0d) cycles",
                                               REGION_N, REGION_N, K_INIT, EPOCH, B_MAX, m,
                                               sched_pkg::t_sub(MESH_N, B_MAX, T_MODE), sched_pkg::t_sub(REGION_N, B_MAX, T_MODE));
    else if (REGION_N == MESH_N) s = $sformatf("design C with one %0dx%0d region (D50), B_MAX %0d, %s subslots of %0d cycles",
                                               REGION_N, REGION_N, B_MAX, m, sched_pkg::t_sub(MESH_N, B_MAX, T_MODE));
    else                         s = $sformatf("design C, %0dx%0d regions, k_L %0d from reset, epoch %0d, B_MAX %0d, %s subslots of %0d (local %0d) cycles",
                                               REGION_N, REGION_N, K_INIT, EPOCH, B_MAX, m,
                                               sched_pkg::t_sub(MESH_N, B_MAX, T_MODE), sched_pkg::t_sub(REGION_N, B_MAX, T_MODE));
    return s;
  endfunction

  initial begin
    for (int i = 0; i < NN; i++) hold_req[i] = '0;
  end

// ---- begin tb/mesh/tests_func.svh

  localparam int unsigned DRAIN_MAX  = 200000;  // cycles allowed to drain one phase
  localparam int unsigned N02_PERIOD = 500;     // N02: one packet per node per period
  localparam int unsigned N06_STEP   = 1000;    // N06: cycles of each step (300 with +QUICK)

  function automatic bit quick();
    return $test$plusargs("QUICK") != 0;
  endfunction

  function automatic real sat_rate();
    real r;
    if (NUM_VC == 1) begin
      case (MESH_N)
        2:       r = 0.102;
        4:       r = 0.0716;
        8:       r = 0.0371;
        default: r = 0.30 / real'(MESH_N);      // not measured
      endcase
    end else begin
      case (MESH_N)
        2:       r = 0.332;
        4:       r = 0.257;
        8:       r = 0.137;
        default: r = 1.1 / real'(MESH_N);       // not measured
      endcase
      if (NUM_VC < 4) r = r * real'(NUM_VC) / 4.0;   // 2 or 3 VCs: not measured
    end
    return r;
  endfunction

  function automatic int unsigned scaled(int unsigned base);
    int unsigned c;
    c = base * 16 / NN;
    return (c < 200) ? 200 : c;
  endfunction

  function automatic real rabs(real x);
    return (x < 0.0) ? -x : x;
  endfunction

  function automatic int unsigned centre();
    return (MESH_N / 2) * MESH_N + MESH_N / 2;
  endfunction

  task automatic stop_if(bit ok, string what);
    if (!ok) begin
      tb_pkg::fail($sformatf("%s: stopping the run, the network did not empty", what));
      tb_pkg::finish();
    end
  endtask

  function automatic string why_stuck(int stalls0, int unsigned dmax);
    string s;
    if (u_rc.stalls != stalls0) s = $sformatf("deadlock, no packet delivered since cycle %0d", sb_pkg::last_delivery);
    else                        s = $sformatf("not drained after %0d cycles", dmax);
    return s;
  endfunction

  task automatic load_phase(string what, int unsigned warm, int unsigned meas);
    bit ok;
    int stalls0;
    stalls0 = u_rc.stalls;
    stats_pkg::reset(NN);
    u_rc.run_load(warm, meas, DRAIN_MAX, ok);
    `TB_CHECK(ok, ("%s: %s", what, why_stuck(stalls0, DRAIN_MAX)))
    stop_if(ok, what);
    `TB_CHECK(stats_pkg::m_left == 0, ("%s: %0d measured packets never delivered", what, stats_pkg::m_left))
    check_idle(what);
  endtask

  function automatic void report(string what);
    string sat;
    sat = "";
    if (stats_pkg::saturated()) sat = ", saturated";
    tb_pkg::info($sformatf("%s: %0d packets measured, latency avg %0.2f p99 %0d max %0d, offered %0.4f accepted %0.4f flits/node/cycle%s",
                           what, stats_pkg::delivered_pkts(), stats_pkg::lat_avg(), stats_pkg::lat_pct(0.99),
                           stats_pkg::lat_max, stats_pkg::thr_off(), stats_pkg::thr_acc(), sat));
  endfunction

  task automatic n01();
    bit              ok;
    longint unsigned d0;
    tb_pkg::phase($sformatf("N01 all pairs: %0d x %0d nodes, one packet per ordered pair, all at once",
                            NN, NN));
    traffic_defaults();
    stats_pkg::reset(NN);
    d0 = sb_pkg::n_delivered;
    traffic_pkg::burst_id++;
    @(posedge clk);                     // the generators queue the burst at the falling edge
    `TB_CHECK(sb_pkg::outstanding() == longint'(NN * NN),
              ("N01: %0d packets queued, expected %0d", sb_pkg::outstanding(), NN * NN))
    u_rc.drain(DRAIN_MAX, ok);
    `TB_CHECK(ok, ("N01: the burst did not drain (deadlock or more than %0d cycles)", DRAIN_MAX))
    stop_if(ok, "N01");
    `TB_CHECK(sb_pkg::n_delivered - d0 == longint'(NN * NN),
              ("N01: %0d packets delivered, expected %0d", sb_pkg::n_delivered - d0, NN * NN))
    tb_pkg::info($sformatf("N01: %0d packets delivered by cycle %0d", sb_pkg::n_delivered - d0, cyc));
    check_idle("N01");
  endtask

  task automatic n02();
    pattern_e    pats   [3];
    real         target [3];
    int unsigned k_per;
    bit          ok;
    real         exp_avg;
    pats   = '{PAT_TRANSPOSE, PAT_BITROT, PAT_SHUFFLE};
    target = '{15.0, 13.0, 13.0};
    k_per  = (400 + NN - 1) / NN;       // periods, about 400 packets per pattern
    if (k_per < 4) k_per = 4;
    if (quick()) k_per = 2;
    tb_pkg::phase($sformatf("N02 zero-load latency: 1 packet/node every %0d cycles, 1-flit, %0d periods",
                            N02_PERIOD, k_per));
    foreach (pats[k]) begin
      traffic_defaults();
      traffic_pkg::pattern = pats[k];
      traffic_pkg::p_data  = 0.0;
      traffic_pkg::period  = int'(N02_PERIOD);
      traffic_pkg::per_t0  = cyc + 1;   // the first falling edge from now
      exp_avg = real'(zero_load(0, 1)) + 4.0 * mean_hops(pats[k], MESH_N);
      if (MESH_N == 4) begin
        `TB_CHECK(rabs(exp_avg - target[k]) < 1.0e-9,
                  ("N02 %s: expected average %0.3f, the tracker says %0.1f", pat_name(pats[k]), exp_avg, target[k]))
      end
      stats_pkg::reset(NN);
      stats_pkg::open_window(cyc + 1, cyc + 1 + k_per * N02_PERIOD);
      traffic_pkg::gen_on = 1'b1;
      u_rc.wait_cycles(k_per * N02_PERIOD, ok);
      traffic_pkg::gen_on = 1'b0;
      if (ok) u_rc.drain(DRAIN_MAX, ok);
      `TB_CHECK(ok, ("N02 %s: did not drain", pat_name(pats[k])))
      stop_if(ok, "N02");
      `TB_CHECK(stats_pkg::m_pkts == longint'(k_per * NN) && stats_pkg::m_left == 0,
                ("N02 %s: %0d packets created and %0d delivered, expected %0d", pat_name(pats[k]),
                 stats_pkg::m_pkts, stats_pkg::delivered_pkts(), k_per * NN))
      `TB_CHECK(rabs(stats_pkg::zl_avg() - exp_avg) < 1.0e-9,
                ("N02 %s: zero-load average of the packets sent %0.4f, expected %0.4f",
                 pat_name(pats[k]), stats_pkg::zl_avg(), exp_avg))
      `TB_CHECK(stats_pkg::lat_avg() - exp_avg <= 1.0,
                ("N02 %s: average latency %0.3f, expected %0.3f within 1 cycle", pat_name(pats[k]),
                 stats_pkg::lat_avg(), exp_avg))
      `TB_CHECK(stats_pkg::zl_share() >= 0.9,
                ("N02 %s: only %0.1f%% of packets at exactly the zero-load latency", pat_name(pats[k]),
                 100.0 * stats_pkg::zl_share()))
      tb_pkg::info($sformatf("N02 %s: average latency %0.3f cycles, expected %0.3f; %0.1f%% of %0d packets at exactly zero-load",
                             pat_name(pats[k]), stats_pkg::lat_avg(), exp_avg, 100.0 * stats_pkg::zl_share(),
                             stats_pkg::delivered_pkts()));
      check_idle($sformatf("N02 %s", pat_name(pats[k])));
    end
    traffic_defaults();
  endtask

  task automatic n03();
    real             loads [3];
    real             s_r;
    int              reps;
    int unsigned     gen;
    longint unsigned p0, pk;
    longint unsigned lmax;
    if (!$value$plusargs("N03_REPS=%d", reps)) reps = quick() ? 1 : 5;
    s_r   = sat_rate();
    loads = '{0.25 * s_r, 0.5 * s_r, 0.9 * s_r};
    gen   = quick() ? 100 : scaled(1000);
    tb_pkg::phase($sformatf("N03 random traffic: %0d patterns x 3 loads (%0.3f %0.3f %0.3f packets/node/cycle) x %0d, %0d cycles each",
                            NUM_PATTERNS, loads[0], loads[1], loads[2], reps, gen));
    for (int k = 0; k < NUM_PATTERNS; k++) begin
      p0   = sb_pkg::n_delivered;
      lmax = 0;
      for (int l = 0; l < 3; l++) begin
        for (int r = 0; r < reps; r++) begin
          traffic_defaults();
          traffic_pkg::pattern   = pattern_e'(k);
          traffic_pkg::rate      = loads[l];
          traffic_pkg::phase_len = int'(gen / 4);   // both phases of PHASE in every run
          load_phase($sformatf("N03 %s load %0d run %0d", pat_name(pattern_e'(k)), l + 1, r + 1), 0, gen);
          if (stats_pkg::lat_max > lmax) lmax = stats_pkg::lat_max;
        end
      end
      pk = sb_pkg::n_delivered - p0;
      tb_pkg::cover_bin($sformatf("N03 %s packets delivered", pat_name(pattern_e'(k))), pk);
      tb_pkg::info($sformatf("N03 %s: %0d packets, worst latency %0d cycles", pat_name(pattern_e'(k)), pk, lmax));
    end
    traffic_defaults();
  endtask

  task automatic n04();
    int unsigned meas, warm;
    meas = quick() ? 500 : scaled(2000);
    warm = meas / 2;
    tb_pkg::phase($sformatf("N04 saturation: uniform at 0.5 and 1.2 x %0.3f packets/node/cycle, %0d + %0d cycles",
                            sat_rate(), warm, meas));
    traffic_defaults();
    traffic_pkg::rate = 0.5 * sat_rate();
    load_phase("N04 0.5 x saturation", warm, meas);
    report("N04 0.5 x saturation");
    `TB_CHECK(!stats_pkg::saturated(), ("N04: 0.5 x saturation flagged saturated (accepted %0.4f of offered %0.4f)",
                                        stats_pkg::thr_acc(), stats_pkg::thr_off()))
    traffic_defaults();
    traffic_pkg::rate = 1.2 * sat_rate();
    load_phase("N04 1.2 x saturation", warm, meas);
    report("N04 1.2 x saturation");
    `TB_CHECK(stats_pkg::saturated(), ("N04: 1.2 x saturation not flagged (accepted %0.4f of offered %0.4f)",
                                       stats_pkg::thr_acc(), stats_pkg::thr_off()))
    traffic_defaults();
  endtask


  function automatic bit waits(int t, int p);
    if (t < 0 || t >= NN || p < 0 || p >= NPORTS) return 1'b0;
    return in_wait[t][p] && in_port[t][p] != P_L;
  endfunction

  function automatic int wait_cycle(output string path);
    int t, p, nt, np, ct, cp, steps, len;
    path = "";
    for (int t0 = 0; t0 < NN; t0++) begin
      for (int p0 = 0; p0 < NPORTS; p0++) begin
        t     = t0;
        p     = p0;
        steps = 0;
        while (steps <= NN * NPORTS && waits(t, p)) begin
          nt = int'(nbr_id(node_id_t'(t), in_port[t][p], MESH_N));
          np = int'(opposite(in_port[t][p]));
          t  = nt;
          p  = np;
          steps++;
        end
        if (steps > NN * NPORTS) begin
          ct  = t;
          cp  = p;
          len = 0;
          do begin
            path = {path, $sformatf(" R%0d.%s", t, tb_pkg::port_name(port_t'(p)))};
            nt   = int'(nbr_id(node_id_t'(t), in_port[t][p], MESH_N));
            np   = int'(opposite(in_port[t][p]));
            t    = nt;
            p    = np;
            len++;
          end while (!(t == ct && p == cp) && len <= NN * NPORTS);
          return len;
        end
      end
    end
    return 0;
  endfunction

  task automatic n05();
    bit              ok;
    int unsigned     t0, lim, moves, t_dl;
    longint unsigned d0;
    real             r5;
    int              clen;
    string           cpath;
    lim = 200000;
    if (!$value$plusargs("N05_RATE=%f", r5)) r5 = 0.6;
    tb_pkg::phase($sformatf("N05 deadlock: adaptive routing, %0d VC, uniform at %0.3f packets/node/cycle, up to %0d cycles",
                            NUM_VC, r5, lim));
    traffic_defaults();
    traffic_pkg::rate = r5;
    stats_pkg::reset(NN);
    t0 = cyc;
    traffic_pkg::gen_on = 1'b1;
    u_rc.wait_cycles(lim, ok);
    traffic_pkg::gen_on = 1'b0;
    `TB_CHECK(!ok && u_rc.stalls == 1, ("N05: no deadlock in %0d cycles", lim))
    if (ok) return;
    tb_pkg::info($sformatf("N05: deadlock detected at cycle %0d; last delivery at cycle %0d, %0d cycles after the load started",
                           cyc, u_rc.t_stall, u_rc.t_stall - t0));
    tb_pkg::info($sformatf("N05: %0d packets delivered before it; %0d created and not delivered, most still in source queues",
                           sb_pkg::n_delivered, sb_pkg::outstanding()));
    d0    = sb_pkg::n_delivered;
    moves = 0;
    repeat (u_rc.dl_limit) begin
      @(posedge clk);
      if (|link_busy) moves++;
    end
    `TB_CHECK(sb_pkg::n_delivered == d0, ("N05: %0d packets delivered after the deadlock", sb_pkg::n_delivered - d0))
    `TB_CHECK(moves == 0, ("N05: flits still moved in %0d cycles after the deadlock", moves))
    `TB_CHECK(!(&tile_idle), ("N05: deadlock reported but every router is empty"))
    if (NUM_VC == 1) begin
      clen = wait_cycle(cpath);
      `TB_CHECK(clen >= 2, ("N05: the mesh is frozen but no cycle of waiting packets exists (a lost credit?)"))
      tb_pkg::info($sformatf("N05: %0d packets wait in a cycle, each for the input VC the next one holds:%s",
                             clen, cpath));
    end
    t_dl = u_rc.t_stall - t0;
    tb_pkg::cover_bin("N05 cycles to deadlock", longint'(t_dl));
  endtask

  task automatic n06();
    int unsigned     m, t3, dl0, step;
    bit              ok;
    longint unsigned b0 [NN];
    longint unsigned n_blk, d_other, in_flits, in_pkts, cap_f, cap_p;
    int              vcs;
    int              stalls0;
    m     = centre();
    step  = quick() ? 300 : N06_STEP;
    vcs   = (NN + 4 * MESH_N * (MESH_N - 1)) * NUM_VC + NN * NUM_VC;
    cap_p = longint'(vcs);
    cap_f = longint'(vcs * VC_DEPTH);
    if (DESIGN != DESIGN_A) begin
      cap_p += longint'(NN * SPACE);
      cap_f += longint'(NN * SPACE);
    end
    t3    = int'(vcs) + 100;
    tb_pkg::phase($sformatf("N06 back-pressure: uniform at %0.3f, 10%% sink stalls; node %0d stops for %0d cycles, then every node for %0d",
                            0.5 * sat_rate(), m, step, t3));
    traffic_defaults();
    traffic_pkg::rate         = 0.5 * sat_rate();
    traffic_pkg::sink_stall_p = 0.1;
    stats_pkg::reset(NN);
    stalls0 = u_rc.stalls;
    stats_pkg::open_window(cyc + 1, cyc + 1 + 2 * step);
    traffic_pkg::gen_on = 1'b1;
    u_rc.wait_cycles(step, ok);
    stop_if(ok, "N06 step 1");
    traffic_pkg::fs_node  = int'(m);
    traffic_pkg::fs_start = cyc + 1;
    traffic_pkg::fs_end   = cyc + 1 + step;
    d_other = sb_pkg::n_delivered;
    u_rc.wait_cycles(step, ok);
    stop_if(ok, "N06 step 2");
    `TB_CHECK(loc_full[m], ("N06: node %0d stopped for %0d cycles but its router's Local output VCs are not all busy", m, step))
    tb_pkg::cover_bin("N06 packets delivered while one sink was stopped", sb_pkg::n_delivered - d_other);
    foreach (b0[i]) b0[i] = v_blocked[i];
    traffic_pkg::rate     = 1.0;
    traffic_pkg::p_data   = 0.0;
    traffic_pkg::fs_node  = FS_ALL;
    traffic_pkg::fs_start = cyc + 1;
    traffic_pkg::fs_end   = cyc + 1 + t3;
    dl0 = u_rc.dl_limit;
    if (u_rc.dl_limit < t3 + 500) u_rc.dl_limit = t3 + 500;
    u_rc.wait_cycles(t3, ok);
    u_rc.dl_limit = dl0;
    stop_if(ok, "N06 step 3");
    n_blk = 0;
    for (int i = 0; i < NN; i++) begin
      `TB_CHECK(v_blocked[i] > b0[i],
                ("N06: every sink stopped for %0d cycles, but node %0d's source was never blocked", t3, i))
      n_blk += v_blocked[i] - b0[i];
    end
    in_pkts  = sum_heads() - sum_pkts();
    in_flits = sum_sent() - sum_taken();
    `TB_CHECK(in_pkts <= cap_p, ("N06: %0d packets inside the mesh, more than its %0d VCs can hold", in_pkts, cap_p))
    `TB_CHECK(in_flits <= cap_f, ("N06: %0d flits inside the mesh, more than its %0d buffer slots", in_flits, cap_f))
    tb_pkg::info($sformatf("N06: every sink stopped: %0d packets (%0d flits) inside the mesh, at most %0d fit (one per VC); every source blocked, %0d cycles in all",
                           in_pkts, in_flits, cap_p, n_blk));
    tb_pkg::cover_bin("N06 source cycles blocked while every sink was stopped", n_blk);
    traffic_pkg::gen_on = 1'b0;
    u_rc.drain(DRAIN_MAX, ok);
    `TB_CHECK(ok, ("N06: did not drain after the sinks restarted"))
    stop_if(ok, "N06");
    `TB_CHECK(u_rc.stalls == stalls0 && stats_pkg::m_left == 0,
              ("N06: %0d measured packets never delivered", stats_pkg::m_left))
    tb_pkg::cover_bin("N06 sink stall cycles", sum_stall());
    report("N06 steps 1-2");
    check_idle("N06");
    traffic_defaults();
  endtask

  task automatic n07();
    pattern_e        pats [3];
    longint unsigned i0;
    int unsigned     meas;
    pats = '{PAT_UNIFORM, PAT_BITCOMP, PAT_HOTSPOT};
    meas = quick() ? 300 : scaled(1500);
    tb_pkg::phase($sformatf("N07 data packets only: uniform, bitcomp, hotspot at %0.3f packets/node/cycle, %0d cycles each",
                            0.3 * sat_rate(), meas));
    i0 = sum_inter();
    foreach (pats[k]) begin
      traffic_defaults();
      traffic_pkg::pattern = pats[k];
      traffic_pkg::p_data  = 1.0;
      traffic_pkg::rate    = 0.3 * sat_rate();
      load_phase($sformatf("N07 %s", pat_name(pats[k])), 0, meas);
      report($sformatf("N07 %s", pat_name(pats[k])));
    end
    if (NUM_VC > 1) begin
      tb_pkg::cover_bin("N07 packets interleaved at a sink", sum_inter() - i0);
    end else begin
      `TB_CHECK(sum_inter() == i0, ("N07: %0d packets interleaved at a sink with one VC", sum_inter() - i0))
    end
    traffic_defaults();
  endtask

  task automatic n08();
    int unsigned n8, done, step;
    bit          ok;
    int          stalls0;
    if (!$value$plusargs("N08_CYCLES=%d", n8)) n8 = quick() ? 2000 : 1000000;
    if (n8 < 2000) n8 = 2000;
    tb_pkg::phase($sformatf("N08 endurance: %0d cycles, uniform at %0.3f packets/node/cycle, then drain",
                            n8, 0.5 * sat_rate()));
    traffic_defaults();
    traffic_pkg::rate = 0.5 * sat_rate();
    stats_pkg::reset(NN);
    stalls0 = u_rc.stalls;
    stats_pkg::open_window(cyc + 1001, cyc + 1 + n8);
    traffic_pkg::gen_on = 1'b1;
    done = 0;
    ok   = 1'b1;
    while (done < n8 && ok) begin
      step = (n8 - done < 100000) ? n8 - done : 100000;
      u_rc.wait_cycles(step, ok);
      done += step;
      if (done % 100000 == 0 && done < n8)
        tb_pkg::info($sformatf("N08: %0d of %0d cycles, %0d packets delivered", done, n8, sb_pkg::n_delivered));
    end
    traffic_pkg::gen_on = 1'b0;
    if (ok) u_rc.drain(DRAIN_MAX, ok);
    `TB_CHECK(ok, ("N08: %s", why_stuck(stalls0, DRAIN_MAX)))
    stop_if(ok, "N08");
    `TB_CHECK(stats_pkg::m_left == 0, ("N08: %0d measured packets never delivered", stats_pkg::m_left))
    `TB_CHECK(!stats_pkg::saturated(), ("N08: half the saturation load flagged saturated"))
    report("N08");
    check_idle("N08");
    traffic_defaults();
  endtask
// ---- end tb/mesh/tests_func.svh
// ---- begin tb/mesh/tests_perf.svh

  bit pf_trace_on = 1'b0;                      // perf_trace runs while it is set

  task automatic perf();
    string       pat_s, run_id, s, pol_s, ep_s, pa_s, pb_s, tr_s;
    pattern_e    pat, pq;
    real         rt, rf, pdata, stall, plocal, hfrac, f, fa, fb;
    int unsigned warm, meas, dmax, c0, trn, plen;
    int          treg, m0, m1, k, kmn, kmx, kch, kprev, gl_max, gl_min, gl_n, gg_max, gg_min, gg_n;
    bit          ok;
    int          stalls0;
    string       dsg;
    longint unsigned q_cyc, q_kl, q_loc;
    perf_pkg::snap_t pa, pb;
    dsg = "B";
    if (DESIGN == DESIGN_A) dsg = "A";
    if (DESIGN == DESIGN_C) dsg = "C";
    if (DESIGN == DESIGN_D) dsg = "D";
    if (!$value$plusargs("PATTERN=%s", pat_s)) pat_s = "uniform";
    if (!pat_parse(pat_s, pat)) begin
      tb_pkg::fail($sformatf("PERF: unknown pattern '%s'", pat_s));
      return;
    end
    if (!$value$plusargs("RATE=%f", rt)) begin
      if ($value$plusargs("RATE_FRAC=%f", rf)) rt = rf * sat_rate();
      else                                     rt = 0.5 * sat_rate();
    end
    if (!$value$plusargs("PDATA=%f", pdata))   pdata = 1.0 / 3.0;
    if (!$value$plusargs("STALL=%f", stall))   stall = 0.0;
    if (!$value$plusargs("WARMUP=%d", warm)) begin
      warm = 2000;
      if (DESIGN == DESIGN_D) warm = 5 * EPOCH;
    end
    if (!$value$plusargs("MEASURE=%d", meas))  meas  = 10000;
    if (!$value$plusargs("DRAIN=%d", dmax))    dmax  = DRAIN_MAX;
    if (!$value$plusargs("TRACE=%d", trn))     trn   = 0;
    if (!$value$plusargs("RUNID=%s", run_id))  run_id = $sformatf("%s_N%0d_V%0d_%s", dsg, MESH_N, NUM_VC, pat_s);
    traffic_defaults();
    if ($value$plusargs("PLOCAL=%f", plocal))  traffic_pkg::p_local  = plocal;
    if ($value$plusargs("TREGION=%d", treg))   traffic_pkg::region_n = treg;
    if ($value$plusargs("HOTFRAC=%f", hfrac))  traffic_pkg::hot_frac = hfrac;
    if ($value$plusargs("PHASE_LEN=%d", plen)) traffic_pkg::phase_len = plen;
    if ($value$plusargs("PHASE_A=%s", pa_s)) begin
      if (pat_parse(pa_s, pq)) traffic_pkg::phase_a = pq;
      else tb_pkg::fail($sformatf("PERF: unknown pattern '%s'", pa_s));
    end
    if ($value$plusargs("PHASE_B=%s", pb_s)) begin
      if (pat_parse(pb_s, pq)) traffic_pkg::phase_b = pq;
      else tb_pkg::fail($sformatf("PERF: unknown pattern '%s'", pb_s));
    end
    pol_s = "-";
    ep_s  = "-";
    if (TWO) ep_s = $sformatf("%0d", EPOCH);
    if (DESIGN == DESIGN_C) pol_s = $sformatf("fixed%0d", K_INIT);
    if (DESIGN == DESIGN_D) begin
      if (ctrl_pol) pol_s = "SQRT";
      else          pol_s = "PROP";
      if (!ctrl_damp) pol_s = {pol_s, "_nodamp"};
      if (K_LO != sched_pkg::K_MIN || K_HI != sched_pkg::k_max(MESH_N)) pol_s = $sformatf("%s_k%0d-%0d", pol_s, K_LO, K_HI);
    end
    tb_pkg::phase($sformatf("PERF %s: %s at %0.4f packets/node/cycle, p_data %0.3f, stall %0.3f, %0d + %0d cycles",
                            run_id, pat_s, rt, pdata, stall, warm, meas));
    traffic_pkg::pattern      = pat;
    traffic_pkg::rate         = rt;
    traffic_pkg::p_data       = pdata;
    traffic_pkg::sink_stall_p = stall;
    stats_pkg::reset(NN);
    stalls0 = u_rc.stalls;
    c0      = cyc;
    pa      = perf_snap();
    q_cyc   = pp_cyc;
    q_kl    = pp_kl;
    q_loc   = pp_loc;
    if (TWO) smon_pkg::the_smon.clear_gaps();
    if (trn > 0) begin
      $display("TRACE,run_id,cycle,pkts,lat_avg,k_L,share_L");
      pf_trace_on = 1'b1;
      fork
        begin
          u_rc.run_load(warm, meas, dmax, ok);
          pf_trace_on = 1'b0;
        end
        perf_trace(run_id, trn, c0);
      join
    end else begin
      u_rc.run_load(warm, meas, dmax, ok);
    end
    pb      = perf_snap();
    `TB_CHECK(ok, ("PERF: %s", why_stuck(stalls0, dmax)))
    stop_if(ok, "PERF");
    `TB_CHECK(stats_pkg::m_left == 0, ("PERF: %0d measured packets never delivered", stats_pkg::m_left))
    report("PERF");
    tb_pkg::info($sformatf("PERF: zero-load latency of the measured packets %0.2f, jain %0.4f, worst flow %0.2f",
                           stats_pkg::zl_avg(), stats_pkg::jain(), stats_pkg::lat_flow_max()));
    tb_pkg::csv({stats_pkg::csv_header(), ",", perf_pkg::header(), ",", perf_pkg::header_two()});
    if (DESIGN == DESIGN_A) begin
      tb_pkg::csv({stats_pkg::csv_row(run_id, dsg, MESH_N, NUM_VC, pat_s, pdata, rt, tb_pkg::seed,
                                      u_rc.stalls, u_rc.t_stall, cyc - c0),
                   ",", perf_pkg::row_na(), ",", perf_pkg::row_two_na()});
    end else if (!TWO) begin
      tb_pkg::info($sformatf("PERF: bypass share %0.2f%% of packets; %0d bursts in %0d turns, %0d turns cancelled",
                             100.0 * stats_pkg::byp_pkt(), pb.used - pa.used, pb.turns - pa.turns, pb.cxl - pa.cxl));
      tb_pkg::csv({stats_pkg::csv_row(run_id, dsg, MESH_N, NUM_VC, pat_s, pdata, rt, tb_pkg::seed,
                                      u_rc.stalls, u_rc.t_stall, cyc - c0, $sformatf("%0d", B_MAX), tmode_name()),
                   ",", perf_pkg::row(pa, pb), ",", perf_pkg::row_two_na()});
    end else begin
      m0  = ep_of(c0);
      m1  = ep_of(cyc);
      kmn = 1000;
      kmx = -1;
      kch = 0;
      kprev = -1;
      tr_s = "";
      for (int m = m0; m <= m1; m++) begin
        k = K_INIT;
        if (DESIGN == DESIGN_D) k = plan_of(m);
        if (k < 0) continue;
        if (k < kmn) kmn = k;
        if (k > kmx) kmx = k;
        if (kprev >= 0 && k != kprev) kch++;
        kprev = k;
        s = $sformatf("%0d", k);
        if (tr_s == "") tr_s = s;
        else            tr_s = {tr_s, ";", s};
      end
      smon_pkg::the_smon.gaps(1'b1, gl_max, gl_min, gl_n);
      smon_pkg::the_smon.gaps(1'b0, gg_max, gg_min, gg_n);
      if (gl_n == 0) gl_max = -1;
      if (gg_n == 0) gg_max = -1;
      q_cyc = pp_cyc - q_cyc;
      q_kl  = pp_kl - q_kl;
      q_loc = pp_loc - q_loc;
      tb_pkg::info($sformatf("PERF: bypass share %0.2f%% of packets; %0d bursts in %0d turns, %0d turns cancelled; k_L %0d..%0d, %0d changes",
                             100.0 * stats_pkg::byp_pkt(), pb.used - pa.used, pb.turns - pa.turns, pb.cxl - pa.cxl, kmn, kmx, kch));
      tb_pkg::info($sformatf("PERF: turns of one pair inside a region every %0d..%0d cycles (%0d pairs), across regions every %0d..%0d (%0d pairs)",
                             gl_min, gl_max, gl_n, gg_min, gg_max, gg_n));
      fb = real'(q_cyc);
      f  = 0.0;
      fa = real'(q_kl);
      if (q_cyc > 0) f = fa / fb;
      s  = $sformatf("%0.3f,%0d,%0d,%0d", f, kmn, kmx, kch);
      f  = 0.0;
      fa = real'(q_loc);
      if (q_cyc > 0) f = fa / fb;
      s = $sformatf("%s,%0.4f,%0d,%0d,%s", s, f, gl_max, gg_max, tr_s);
      tb_pkg::csv({stats_pkg::csv_row(run_id, dsg, MESH_N, NUM_VC, pat_s, pdata, rt, tb_pkg::seed,
                                      u_rc.stalls, u_rc.t_stall, cyc - c0, $sformatf("%0d", B_MAX), tmode_name(),
                                      pol_s, ep_s),
                   ",", perf_pkg::row(pa, pb), ",", s});
    end
    check_idle("PERF");
    traffic_defaults();
  endtask

  task automatic perf_trace(string run_id, int unsigned n, int unsigned c0);
    int unsigned     k;
    longint unsigned np, sl, q0c, q0l, dc, dl;
    real             la, sh, fa, fb;
    int              kl;
    k   = 0;
    q0c = pp_cyc;
    q0l = pp_loc;
    stats_pkg::trace_take(np, sl);
    while (pf_trace_on) begin
      @(posedge clk);
      k++;
      if (k == n) begin
        k  = 0;
        stats_pkg::trace_take(np, sl);
        la = 0.0;
        fa = real'(sl);
        fb = real'(np);
        if (np > 0) la = fa / fb;
        dc  = pp_cyc - q0c;
        dl  = pp_loc - q0l;
        q0c = pp_cyc;
        q0l = pp_loc;
        sh  = 0.0;
        fa  = real'(dl);
        fb  = real'(dc);
        if (dc > 0) sh = fa / fb;
        kl  = int'(p_st[0].kl);
        $display("TRACE,%s,%0d,%0d,%0.2f,%0d,%0.4f", run_id, cyc - c0, np, la, kl, sh);
      end
    end
  endtask
// ---- end tb/mesh/tests_perf.svh
// ---- begin tb/mesh/tests_bypass.svh

  localparam int BT  = sched_pkg::t_sub(MESH_N, B_MAX, T_MODE);   // subslot, cycles
  localparam int BS  = sched_pkg::s_setup(MESH_N);                // setup window
  localparam int BSL = sched_pkg::slot_len(MESH_N, BT);
  localparam int BRL = sched_pkg::n_slots(MESH_N) * BSL;          // round
  localparam int BNS = sched_pkg::n_slots(MESH_N);
  localparam int BYP_WAIT = 200000;                               // cycles a directed test may wait
  localparam int BYP_LEAD = 30;                                   // inject this long before the subslot

  function automatic int unsigned sub_start(int sl, int k, int unsigned at_least);
    longint off, t0, r;
    off = longint'(sl) * longint'(BSL) + longint'(BS) + longint'(k) * longint'(BT);
    t0  = longint'(c_rst) + off;
    if (longint'(at_least) <= t0) return int'(t0);
    r = (longint'(at_least) - t0 + longint'(BRL) - 1) / longint'(BRL);
    return int'(t0 + r * longint'(BRL));
  endfunction

  function automatic bit find_sub(int src, int dst, output int sl, output int k, output bit mode);
    sched_ref_pkg::xfer_q_t q;
    sl   = -1;
    k    = -1;
    mode = 1'b0;
    for (int s = 0; s < BNS; s++) begin
      for (int kk = 0; kk < MESH_N; kk++) begin
        q = sched_ref_pkg::ref_xfers(MESH_N, s, kk, 1'b0);
        foreach (q[m]) begin
          if (q[m].sy * MESH_N + q[m].sx == src && q[m].dy * MESH_N + q[m].dx == dst) begin
            sl   = s;
            k    = kk;
            mode = q[m].mode;
          end
        end
      end
    end
    return sl >= 0;
  endfunction

  function automatic int nhops(int a, int b);
    return hops(coord_t'(a % MESH_N), coord_t'(a / MESH_N), coord_t'(b % MESH_N), coord_t'(b / MESH_N));
  endfunction

  task automatic at_cycle(int unsigned c);
    if (cyc > c) begin
      @(posedge clk);
      return;
    end
    while (cyc < c) @(negedge clk);
    @(posedge clk);
  endtask

  task automatic wait_delivered(string what);
    int unsigned     t0;
    longint unsigned left;               // D41: no call in the loop condition
    t0   = cyc;
    left = sb_pkg::outstanding();
    while (left != 0 && cyc - t0 < BYP_WAIT) begin
      @(negedge clk);
      left = sb_pkg::outstanding();
    end
    `TB_CHECK(left == 0, ("%s: %0d packets not delivered after %0d cycles", what, left, BYP_WAIT))
    stop_if(left == 0, what);
  endtask

  function automatic bit find_dlog(int src, int unsigned seq, output traffic_pkg::dlog_t d);
    d = '0;
    foreach (traffic_pkg::dlog[i]) begin
      if (int'(traffic_pkg::dlog[i].src) == src && traffic_pkg::dlog[i].seq == seq) begin
        d = traffic_pkg::dlog[i];
        return 1'b1;
      end
    end
    return 1'b0;
  endfunction

  function automatic longint unsigned sum_of(longint unsigned a [NN]);
    longint unsigned s;
    s = 0;
    for (int i = 0; i < NN; i++) s += a[i];
    return s;
  endfunction

  function automatic int get_burst_pkts(int src, int unsigned t, output int psrc [16], output int pseq [16],
                                        output int plen [16]);
    int np;
    np = 0;
    for (int i = 0; i < 16; i++) begin
      psrc[i] = -1;
      pseq[i] = -1;
      plen[i] = 0;
    end
    if (rchk_pkg::the_chk == null) return 0;
    np = rchk_pkg::the_chk.burst_pkts(src, int'(t), psrc, pseq, plen);
    return np;
  endfunction

  /* verilator lint_off UNUSEDSIGNAL */
  task automatic check_burst(string what, int src, int dst, int unsigned t, int exp_len, output int got_len);
    int                 np, L, j, psrc [16], pseq [16], plen [16];
    traffic_pkg::dlog_t d;
    bit                 ok;
    L       = nhops(src, dst);
    got_len = (rchk_pkg::the_chk == null) ? -1 : rchk_pkg::the_chk.burst_len(src, int'(t));
    if (exp_len > 0) begin
      `TB_CHECK(got_len == exp_len, ("%s: the burst R%0d->R%0d at cycle %0d has %0d flits, expected %0d",
                                     what, src, dst, t, got_len, exp_len))
    end else begin
      `TB_CHECK(got_len >= 1 && got_len <= B_MAX, ("%s: the burst R%0d->R%0d at cycle %0d has %0d flits",
                                                   what, src, dst, t, got_len))
    end
    np = get_burst_pkts(src, t, psrc, pseq, plen);
    j  = 0;
    for (int i = 0; i < np; i++) begin
      j  = j + plen[i];
      ok = find_dlog(psrc[i], pseq[i], d);
      `TB_CHECK(ok && d.byp && int'(d.dst) == dst && d.t_tail == t + sched_pkg::tc_eject(L, j - 1),
                ("%s: packet %0d.%0d of the burst R%0d->R%0d (flits %0d-%0d): delivered %0b, bypass %0b, at R%0d, tail at cycle %0d, expected t + 2L + 3 + %0d = %0d",
                 what, psrc[i], pseq[i], src, dst, j - plen[i], j - 1, ok, d.byp, d.dst, d.t_tail, j - 1,
                 t + sched_pkg::tc_eject(L, j - 1)))
    end
    `TB_CHECK(j == got_len, ("%s: the burst's packets add up to %0d flits, the burst has %0d", what, j, got_len))
  endtask
  /* verilator lint_on UNUSEDSIGNAL */

  task automatic bp01();
    int          src, dst, sl, k, L, blen, nev0, nev;
    bit          mode, ok;
    int unsigned t;
    tb_pkg::phase("BP01 one bypass at the exact cycles: a 5-flit packet held at its source until its subslot");
    traffic_defaults();
    traffic_pkg::dlog.delete();
    traffic_pkg::log_on = 1'b1;
    if (MESH_N == 2) begin
      src = 1;                           // (1,0) -> (0,1)
      dst = 2;
    end else begin
      src = 2;                           // (2,0) -> (1,2): R2 -> R9 on 4x4
      dst = 2 * MESH_N + 1;
    end
    ok = find_sub(src, dst, sl, k, mode);
    L  = nhops(src, dst);
    `TB_CHECK(ok, ("BP01: the timetable never lets R%0d send to R%0d", src, dst))
    if (MESH_N == 4) begin
      `TB_CHECK(sl == 8 && k == 2 && mode == MODE_XY,
                ("BP01: R2 -> R9 in slot %0d, subslot %0d, mode %0d; Table I and Fig. 3 of [1] say slot 8, subslot 2, XY",
                 sl, k, mode))
    end
    t = sub_start(sl, k, cyc + BYP_LEAD + 2);
    tb_pkg::info($sformatf("BP01: R%0d -> R%0d, %0d hops, slot %0d subslot %0d by %s; the subslot starts at cycle %0d",
                           src, dst, L, sl, k, (mode == MODE_XY) ? "XY" : "YX", t));
    nev0 = (rchk_pkg::the_chk == null) ? 0 : int'(rchk_pkg::the_chk.n_ev);
    at_cycle(t - BYP_LEAD);
    hold_req[src] = 5'b10000;            // Local input: the packet waits in its VC
    traffic_pkg::direct(src, dst, MAX_PKT_FLITS);
    at_cycle(t - 1);
    hold_req[src] = '0;                  // off in cycle t: the source's hold must win
    wait_delivered("BP01");
    check_burst("BP01", src, dst, t, MAX_PKT_FLITS, blen);
    nev = (rchk_pkg::the_chk == null) ? -1 : int'(rchk_pkg::the_chk.n_ev) - nev0;
    `TB_CHECK(nev == (L - 1) + MAX_PKT_FLITS * L + MAX_PKT_FLITS,
              ("BP01: the checker matched %0d lookahead, link and NI events, expected %0d", nev,
               (L - 1) + MAX_PKT_FLITS * L + MAX_PKT_FLITS))
    `TB_CHECK(traffic_pkg::dlog.size() == 1, ("BP01: %0d packets delivered, expected 1", traffic_pkg::dlog.size()))
    if (traffic_pkg::dlog.size() == 1) begin
      tb_pkg::info($sformatf("BP01: created at cycle %0d, burst of %0d flits decided at %0d, lookahead on link 1 at %0d, flit 0 on link 1 at %0d, tail in R%0d's NI at %0d: latency %0d cycles (regular zero-load %0d)",
                             traffic_pkg::dlog[0].t_create, blen, t, t + sched_pkg::tc_la(1), t + sched_pkg::tc_link(1, 0),
                             dst, traffic_pkg::dlog[0].t_tail, traffic_pkg::dlog[0].t_tail - traffic_pkg::dlog[0].t_create,
                             zero_load(L, MAX_PKT_FLITS)));
    end
    traffic_pkg::log_on = 1'b0;
    check_idle("BP01");
    traffic_defaults();
  endtask

  function automatic int unsigned act_t(int unsigned t [4], int a);
    if (a < 4) return t[a] - BYP_LEAD;
    return t[a - 4] - 1;
  endfunction

  task automatic bp02();
    int          src [4], dst [4], len2 [4], sl [4], k [4], blen, ord [8], tmp, exp;
    bit          mode [4], ok;
    int unsigned t [4];
    tb_pkg::phase($sformatf("BP02 corner to corner, both ways: %0d hops, two-packet bursts", 2 * (MESH_N - 1)));
    traffic_defaults();
    traffic_pkg::dlog.delete();
    traffic_pkg::log_on = 1'b1;
    src  = '{0, NN - 1, MESH_N - 1, NN - MESH_N};
    dst  = '{NN - 1, 0, NN - MESH_N, MESH_N - 1};
    len2 = '{MAX_PKT_FLITS, 1, MAX_PKT_FLITS, 1};      // second packet: bursts of 10 and 6 flits
    for (int i = 0; i < 4; i++) begin
      ok = find_sub(src[i], dst[i], sl[i], k[i], mode[i]);
      `TB_CHECK(ok && nhops(src[i], dst[i]) == 2 * (MESH_N - 1),
                ("BP02: R%0d -> R%0d not in the timetable or not a longest path", src[i], dst[i]))
      t[i] = sub_start(sl[i], k[i], cyc + BYP_LEAD + 2);
      tb_pkg::info($sformatf("BP02: R%0d -> R%0d in slot %0d subslot %0d by %s, at cycle %0d: %0d + %0d flits",
                             src[i], dst[i], sl[i], k[i], (mode[i] == MODE_XY) ? "XY" : "YX", t[i],
                             MAX_PKT_FLITS, len2[i]));
    end
    for (int i = 0; i < 8; i++) ord[i] = i;
    for (int i = 0; i < 8; i++) begin
      for (int j = 0; j < 7 - i; j++) begin
        if (act_t(t, ord[j]) > act_t(t, ord[j + 1])) begin
          tmp        = ord[j];
          ord[j]     = ord[j + 1];
          ord[j + 1] = tmp;
        end
      end
    end
    for (int i = 0; i < 8; i++) begin
      at_cycle(act_t(t, ord[i]));
      if (ord[i] < 4) begin
        hold_req[src[ord[i]]] = 5'b10000;
        traffic_pkg::direct(src[ord[i]], dst[ord[i]], MAX_PKT_FLITS);
        traffic_pkg::direct(src[ord[i]], dst[ord[i]], len2[ord[i]]);
      end else begin
        hold_req[src[ord[i] - 4]] = '0;
      end
    end
    wait_delivered("BP02");
    for (int i = 0; i < 4; i++) begin
      if (NUM_VC == 1)                          exp = MAX_PKT_FLITS;
      else if (MAX_PKT_FLITS + len2[i] <= B_MAX) exp = MAX_PKT_FLITS + len2[i];
      else                                      exp = 0;
      check_burst($sformatf("BP02 R%0d->R%0d", src[i], dst[i]), src[i], dst[i], t[i], exp, blen);
      tb_pkg::info($sformatf("BP02: R%0d -> R%0d: %0d flits left at cycle %0d, the last in R%0d's NI at cycle %0d (t + %0d; the subslot has %0d cycles)",
                             src[i], dst[i], blen, t[i], dst[i], t[i] + sched_pkg::tc_eject(2 * (MESH_N - 1), blen - 1),
                             sched_pkg::tc_eject(2 * (MESH_N - 1), blen - 1), BT));
    end
    `TB_CHECK(traffic_pkg::dlog.size() == 8, ("BP02: %0d packets delivered, expected 8", traffic_pkg::dlog.size()))
    check_idle("BP02");
    if (MESH_N >= 3) bp02b();
    traffic_pkg::log_on = 1'b0;
    traffic_defaults();
  endtask

  function automatic bit burst_mix(int b, output int n5, output int n1);
    for (int a = 2; a >= 0; a--) begin
      if (b - MAX_PKT_FLITS * a >= 0 && a + (b - MAX_PKT_FLITS * a) <= NUM_VC && b <= B_MAX) begin
        n5 = a;
        n1 = b - MAX_PKT_FLITS * a;
        return 1'b1;
      end
    end
    n5 = 0;
    n1 = 0;
    return 1'b0;
  endfunction

  function automatic bit find_abut(output int sl, output int k, output int sa, output int da, output int sb,
                                   output int db, output int ba, output int ia, output int ib);
    sched_ref_pkg::xfer_q_t qa, qb;
    sched_ref_pkg::link_q_t pa, pb;
    int                     n5, n1;
    for (int s = 0; s < BNS; s++) begin
      for (int kk = 0; kk + 1 < MESH_N; kk++) begin
        qa = sched_ref_pkg::ref_xfers(MESH_N, s, kk, 1'b0);
        qb = sched_ref_pkg::ref_xfers(MESH_N, s, kk + 1, 1'b0);
        foreach (qa[m]) begin
          pa = sched_ref_pkg::ref_path(qa[m].sx, qa[m].sy, qa[m].dx, qa[m].dy, qa[m].mode);
          foreach (qb[m2]) begin
            pb = sched_ref_pkg::ref_path(qb[m2].sx, qb[m2].sy, qb[m2].dx, qb[m2].dy, qb[m2].mode);
            foreach (pa[h]) begin
              foreach (pb[h2]) begin
                if (pa[h].x == pb[h2].x && pa[h].y == pb[h2].y && pa[h].p == pb[h2].p &&
                    BT + 2 * (h2 + 1) - 2 * (h + 1) >= 1 &&
                    burst_mix(BT + 2 * (h2 + 1) - 2 * (h + 1), n5, n1) && n5 + n1 >= 1) begin
                  sl = s;
                  k  = kk;
                  sa = qa[m].sy * MESH_N + qa[m].sx;
                  da = qa[m].dy * MESH_N + qa[m].dx;
                  sb = qb[m2].sy * MESH_N + qb[m2].sx;
                  db = qb[m2].dy * MESH_N + qb[m2].dx;
                  ia = h + 1;
                  ib = h2 + 1;
                  ba = BT + 2 * ib - 2 * ia;
                  return 1'b1;
                end
              end
            end
          end
        end
      end
    end
    return 1'b0;
  endfunction

  task automatic bp02b();
    int              sl, k, sa, da, sb, db, ba, ia, ib, n5, n1, blen;
    bit              ok;
    int unsigned     t;
    longint unsigned a0;
    traffic_pkg::dlog.delete();
    ok = find_abut(sl, k, sa, da, sb, db, ba, ia, ib);
    if (!ok) begin
      tb_pkg::info($sformatf("BP02 back to back: no two bursts of consecutive subslots can meet back to back on a link in this timetable (%0dx%0d, T = %0d)",
                             MESH_N, MESH_N, BT));
      return;
    end
    ok = burst_mix(ba, n5, n1);
    t  = sub_start(sl, k, cyc + BYP_LEAD + 2);
    tb_pkg::info($sformatf("BP02 back to back: slot %0d subslot %0d at cycle %0d: R%0d -> R%0d (%0d flits) uses on its link %0d the link that R%0d -> R%0d uses as its link %0d in the next subslot",
                           sl, k, t, sa, da, ba, ia, sb, db, ib));
    a0 = sum_of(v_abut);
    at_cycle(t - BYP_LEAD);
    hold_req[sa] = 5'b10000;
    for (int i = 0; i < n5; i++) traffic_pkg::direct(sa, da, MAX_PKT_FLITS);
    for (int i = 0; i < n1; i++) traffic_pkg::direct(sa, da, 1);
    at_cycle(t + BT - BYP_LEAD);
    hold_req[sb] = 5'b10000;
    traffic_pkg::direct(sb, db, MAX_PKT_FLITS);
    at_cycle(t - 1);
    hold_req[sa] = '0;
    at_cycle(t + BT - 1);
    hold_req[sb] = '0;
    wait_delivered("BP02 back to back");
    check_burst($sformatf("BP02 R%0d->R%0d", sa, da), sa, da, t, ba, blen);
    tb_pkg::info($sformatf("BP02 back to back: A's last flit crosses the shared link's far router at cycle %0d (t + %0d), B's lookahead reaches it then",
                           t + 2 * ia + blen, 2 * ia + blen));
    check_burst($sformatf("BP02 R%0d->R%0d", sb, db), sb, db, t + BT, MAX_PKT_FLITS, blen);
    tb_pkg::cover_bin("BP02 bursts back to back on one link", sum_of(v_abut) - a0);
    check_idle("BP02 back to back");
  endtask

  task automatic check_maximal(string what, int src, int unsigned t, int nw, int wsrc [8], int wseq [8], int wlen [8],
                               output int n_from);
    int  np, psrc [16], pseq [16], plen [16], sum, left_min;
    bit  in_burst;
    np       = get_burst_pkts(src, t, psrc, pseq, plen);
    sum      = 0;
    left_min = 1000;
    n_from   = 0;
    for (int i = 0; i < np; i++) sum += plen[i];
    for (int w = 0; w < nw; w++) begin
      in_burst = 1'b0;
      for (int i = 0; i < np; i++) begin
        if (psrc[i] == wsrc[w] && pseq[i] == wseq[w]) in_burst = 1'b1;
      end
      if (!in_burst && wlen[w] < left_min) left_min = wlen[w];
      if (in_burst && wsrc[w] != src) n_from++;
    end
    for (int i = 0; i < np; i++) begin
      in_burst = 1'b0;
      for (int w = 0; w < nw; w++) begin
        if (psrc[i] == wsrc[w] && pseq[i] == wseq[w]) in_burst = 1'b1;
      end
      `TB_CHECK(in_burst, ("%s: the burst carries packet %0d.%0d, which was not waiting", what, psrc[i], pseq[i]))
    end
    `TB_CHECK(np >= 1 && sum <= B_MAX && (left_min == 1000 || sum + left_min > B_MAX),
              ("%s: the burst takes %0d packets, %0d flits (B_MAX %0d); the shortest packet left waiting has %0d flits",
               what, np, sum, B_MAX, left_min))
    tb_pkg::info($sformatf("%s: %0d of %0d waiting packets sent, %0d flits; %0d of them from another router's packets",
                           what, np, nw, sum, n_from));
  endtask

  task automatic bp04();
    int          s, d, e, sl, k, blen, nw, n_from, exp;
    int          wsrc [8], wseq [8], wlen [8];
    bit          mode, ok;
    int unsigned t;
    tb_pkg::phase($sformatf("BP04 the burst limit: more eligible flits than B_MAX = %0d", B_MAX));
    traffic_defaults();
    traffic_pkg::dlog.delete();
    traffic_pkg::log_on = 1'b1;
    s  = (MESH_N / 2) * MESH_N + MESH_N / 2;
    d  = 0;
    ok = find_sub(s, d, sl, k, mode);
    `TB_CHECK(ok, ("BP04: the timetable never lets R%0d send to R%0d", s, d))
    t  = sub_start(sl, k, cyc + BYP_LEAD + 2);
    tb_pkg::info($sformatf("BP04 a: R%0d -> R%0d at cycle %0d (slot %0d subslot %0d, %s): %0d five-flit packets waiting",
                           s, d, t, sl, k, (mode == MODE_XY) ? "XY" : "YX", NUM_VC));
    at_cycle(t - BYP_LEAD);
    hold_req[s] = 5'b10000;
    for (int i = 0; i < NUM_VC; i++) traffic_pkg::direct(s, d, MAX_PKT_FLITS);
    at_cycle(t - 1);
    hold_req[s] = '0;
    wait_delivered("BP04 a");
    exp = B_MAX / MAX_PKT_FLITS;
    if (exp > NUM_VC) exp = NUM_VC;
    check_burst("BP04 a", s, d, t, exp * MAX_PKT_FLITS, blen);
    nw = 0;
    foreach (traffic_pkg::dlog[i]) begin
      if (nw < 8) begin
        wsrc[nw] = int'(traffic_pkg::dlog[i].src);
        wseq[nw] = int'(traffic_pkg::dlog[i].seq);
        wlen[nw] = int'(traffic_pkg::dlog[i].len);
        nw++;
      end
    end
    check_maximal("BP04 a", s, t, nw, wsrc, wseq, wlen, n_from);
    nw = 0;
    foreach (traffic_pkg::dlog[i]) if (!traffic_pkg::dlog[i].byp) nw++;
    `TB_CHECK(traffic_pkg::dlog.size() == NUM_VC, ("BP04 a: %0d packets delivered, expected %0d",
                                                   traffic_pkg::dlog.size(), NUM_VC))
    tb_pkg::info($sformatf("BP04 a: the %0d packets left out arrived later, %0d of them by the regular path",
                           NUM_VC - blen / MAX_PKT_FLITS, nw));
    check_idle("BP04 a");
    if (MESH_N >= 3) begin
      traffic_pkg::dlog.delete();
      s  = (MESH_N - 1) * MESH_N + 1;    // (1, n-1)
      d  = s - 1;                        // its west neighbour
      e  = s + 1;                        // its east neighbour: its packets for d pass s
      ok = find_sub(s, d, sl, k, mode);
      `TB_CHECK(ok, ("BP04: the timetable never lets R%0d send to R%0d", s, d))
      t  = sub_start(sl, k, cyc + BYP_LEAD + 2);
      tb_pkg::info($sformatf("BP04 b: R%0d -> R%0d at cycle %0d; R%0d's packets for R%0d wait in R%0d's East input",
                             s, d, t, e, d, s));
      at_cycle(t - BYP_LEAD);
      hold_req[s] = 5'b10010;            // East and Local inputs
      traffic_pkg::direct(e, d, MAX_PKT_FLITS);
      traffic_pkg::direct(e, d, 1);
      traffic_pkg::direct(s, d, MAX_PKT_FLITS);
      at_cycle(t - 1);
      hold_req[s] = '0;
      wait_delivered("BP04 b");
      check_burst("BP04 b", s, d, t, 0, blen);
      nw = 0;
      foreach (traffic_pkg::dlog[i]) begin
        if (nw < 8) begin
          wsrc[nw] = int'(traffic_pkg::dlog[i].src);
          wseq[nw] = int'(traffic_pkg::dlog[i].seq);
          wlen[nw] = int'(traffic_pkg::dlog[i].len);
          nw++;
        end
      end
      `TB_CHECK(nw == 3, ("BP04 b: %0d packets delivered, expected 3", nw))
      check_maximal("BP04 b", s, t, nw, wsrc, wseq, wlen, n_from);
      if (B_MAX >= 2 * MAX_PKT_FLITS) begin
        `TB_CHECK(n_from >= 1, ("BP04 b: the burst took no packet from R%0d's East input", s))
        tb_pkg::cover_bin("BP04 packets bypassed from a mesh input of a router on their path", longint'(n_from));
      end else begin
        tb_pkg::cover_goal("BP04 packets bypassed from a mesh input of a router on their path", longint'(n_from));
      end
      check_idle("BP04 b");
      bp04c();
    end
    if (BT == B_MAX && NUM_VC >= 3) bp04d();
    traffic_pkg::log_on = 1'b0;
    traffic_defaults();
  endtask

  function automatic bit find_two_turns(output int sl, output int k, output int sr, output int d1, output int d2);
    sched_ref_pkg::xfer_q_t qa, qb;
    for (int s = 0; s < BNS; s++) begin
      for (int kk = 0; kk + 1 < MESH_N; kk++) begin
        qa = sched_ref_pkg::ref_xfers(MESH_N, s, kk, 1'b0);
        qb = sched_ref_pkg::ref_xfers(MESH_N, s, kk + 1, 1'b0);
        foreach (qa[m]) begin
          foreach (qb[m2]) begin
            if (qa[m].sx == qb[m2].sx && qa[m].sy == qb[m2].sy) begin
              sl = s;
              k  = kk;
              sr = qa[m].sy * MESH_N + qa[m].sx;
              d1 = qa[m].dy * MESH_N + qa[m].dx;
              d2 = qb[m2].dy * MESH_N + qb[m2].dx;
              return 1'b1;
            end
          end
        end
      end
    end
    return 1'b0;
  endfunction

  task automatic bp04d();
    int              sl, k, sr, d1, d2, blen;
    bit              ok;
    int unsigned     t;
    longint unsigned z0;
    traffic_pkg::dlog.delete();
    ok = find_two_turns(sl, k, sr, d1, d2);
    `TB_CHECK(ok, ("BP04 d: no router sends in two consecutive subslots"))
    if (!ok) return;
    t  = sub_start(sl, k, cyc + BYP_LEAD + 2);
    tb_pkg::info($sformatf("BP04 d: R%0d sends %0d flits to R%0d at cycle %0d and chooses its burst to R%0d at cycle %0d, as the last flit leaves",
                           sr, B_MAX, d1, t, d2, t + BT));
    z0 = sum_of(v_b2b);
    at_cycle(t - BYP_LEAD);
    hold_req[sr] = 5'b10000;
    traffic_pkg::direct(sr, d1, MAX_PKT_FLITS);
    traffic_pkg::direct(sr, d1, MAX_PKT_FLITS);
    traffic_pkg::direct(sr, d2, MAX_PKT_FLITS);
    at_cycle(t - 1);
    hold_req[sr] = '0;
    wait_delivered("BP04 d");
    check_burst($sformatf("BP04 d R%0d->R%0d", sr, d1), sr, d1, t, 2 * MAX_PKT_FLITS, blen);
    tb_pkg::info($sformatf("BP04 d: the first burst's last flit left R%0d at cycle %0d", sr, t + sched_pkg::tc_xbar(blen - 1)));
    check_burst($sformatf("BP04 d R%0d->R%0d", sr, d2), sr, d2, t + BT, MAX_PKT_FLITS, blen);
    tb_pkg::cover_bin("BP04 bursts chosen as the previous burst sent its last flit", sum_of(v_b2b) - z0);
    check_idle("BP04 d");
  endtask

  function automatic bit find_rule_case(output int sl, output int k, output int x, output int y, output int sr,
                                        output int d, output int pin);
    sched_ref_pkg::xfer_q_t q;
    sched_ref_pkg::link_q_t pth;
    int                     ex, ey, sx, sy, dx, dy;
    for (int s = 0; s < BNS; s++) begin
      for (int kk = 0; kk < MESH_N; kk++) begin
        q = sched_ref_pkg::ref_xfers(MESH_N, s, kk, 1'b0);
        foreach (q[m]) begin
          pth = sched_ref_pkg::ref_path(q[m].sx, q[m].sy, q[m].dx, q[m].dy, q[m].mode);
          if (pth.size() >= 2) begin
            sched_ref_pkg::ref_link_end(pth[0], ex, ey);          // S
            foreach (q[n2]) begin
              if (q[n2].sx == ex && q[n2].sy == ey) begin
                sx = q[m].sx;
                sy = q[m].sy;
                dx = q[n2].dx;
                dy = q[n2].dy;
                if ((pth[0].p == int'(P_E) && dx >= ex) || (pth[0].p == int'(P_W) && dx <= ex) ||
                    (pth[0].p == int'(P_S) && dx == sx && dy > ey) || (pth[0].p == int'(P_N) && dx == sx && dy < ey)) begin
                  sl  = s;
                  k   = kk;
                  x   = sy * MESH_N + sx;
                  y   = q[m].dy * MESH_N + q[m].dx;
                  sr  = ey * MESH_N + ex;
                  d   = dy * MESH_N + dx;
                  pin = sched_ref_pkg::ref_opposite(pth[0].p);
                  return 1'b1;
                end
              end
            end
          end
        end
      end
    end
    return 1'b0;
  endfunction

  task automatic bp04c();
    int          sl, k, x, y, sr, d, pin, blen, exp;
    bit          ok;
    int unsigned t;
    longint unsigned u0;
    traffic_pkg::dlog.delete();
    ok = find_rule_case(sl, k, x, y, sr, d, pin);
    `TB_CHECK(ok, ("BP04 c: no subslot where a source's mesh input is crossed by a passing burst"))
    if (!ok) return;
    t  = sub_start(sl, k, cyc + BYP_LEAD + 22);
    tb_pkg::info($sformatf("BP04 c: slot %0d subslot %0d at cycle %0d: R%0d -> R%0d passes R%0d, entering on its %s input, while R%0d sends to R%0d a packet from R%0d waiting in that same input",
                           sl, k, t, x, y, sr, tb_pkg::port_name(port_t'(pin)), sr, d, x));
    u0 = sum_of(v_rule);
    at_cycle(t - BYP_LEAD - 20);
    hold_req[sr] = NPORTS'(1) << pin;
    traffic_pkg::direct(x, d, MAX_PKT_FLITS);
    at_cycle(t - BYP_LEAD);
    hold_req[x] = 5'b10000;
    traffic_pkg::direct(x, y, MAX_PKT_FLITS);
    traffic_pkg::direct(x, y, MAX_PKT_FLITS);
    at_cycle(t - 1);
    hold_req[sr] = '0;
    hold_req[x]  = '0;
    wait_delivered("BP04 c");
    exp = B_MAX / MAX_PKT_FLITS;
    if (exp > NUM_VC) exp = NUM_VC;
    if (exp > 2)      exp = 2;
    check_burst($sformatf("BP04 c R%0d->R%0d", sr, d), sr, d, t, MAX_PKT_FLITS, blen);
    check_burst($sformatf("BP04 c R%0d->R%0d", x, y), x, y, t, exp * MAX_PKT_FLITS, blen);
    tb_pkg::info($sformatf("BP04 c: R%0d's burst of %0d flits crossed R%0d at cycles %0d-%0d while R%0d's own flits left at %0d-%0d",
                           x, blen, sr, t + sched_pkg::tc_link(1, 0), t + sched_pkg::tc_link(1, blen - 1), sr,
                           t + sched_pkg::tc_xbar(0), t + sched_pkg::tc_xbar(MAX_PKT_FLITS - 1)));
    tb_pkg::cover_bin("BP04 cycles a source read a mesh input that a passing burst crossed (D38 rule)", sum_of(v_rule) - u0);
    check_idle("BP04 c");
  endtask

  task automatic bp05();
    int unsigned     meas;
    longint unsigned b0, f0, p0, m0, r0, u0, w0, x0, a0, z0, ck0, ckb0;
    real             share;
    meas = quick() ? 1000 : scaled(4000);
    if (meas < sched_pkg::round_len(MESH_N, sched_pkg::t_sub(MESH_N, B_MAX, T_MODE)))
      meas = sched_pkg::round_len(MESH_N, sched_pkg::t_sub(MESH_N, B_MAX, T_MODE));
    tb_pkg::phase($sformatf("BP05 bypass under heavy traffic: uniform at 0.9 x %0.3f packets/node/cycle, %0d cycles",
                            sat_rate(), meas));
    traffic_defaults();
    traffic_pkg::rate = 0.9 * sat_rate();
    b0   = sum_of(v_used);
    f0   = sum_of(v_bflits);
    p0   = sum_of(v_bpkts);
    m0   = sum_of(v_multi);
    r0   = sum_of(v_remote);
    u0   = sum_of(v_rule);
    w0   = sum_of(v_turns);
    x0   = sum_of(v_full);
    a0   = sum_of(v_abut);
    z0   = sum_of(v_b2b);
    ck0  = (rchk_pkg::the_chk == null) ? 0 : rchk_pkg::the_chk.n_ev;
    ckb0 = (rchk_pkg::the_chk == null) ? 0 : rchk_pkg::the_chk.n_bursts;
    load_phase("BP05", meas / 4, meas);
    report("BP05");
    share = stats_pkg::byp_pkt();
    tb_pkg::info($sformatf("BP05: %0d bursts in %0d turns, %0d packets (%0d flits) by bypass; %0d bursts of several packets, %0d of exactly B_MAX flits; %0d packets taken from mesh inputs; bypass share %0.1f%% of packets, %0.1f%% of flits",
                           sum_of(v_used) - b0, sum_of(v_turns) - w0, sum_of(v_bpkts) - p0, sum_of(v_bflits) - f0,
                           sum_of(v_multi) - m0, sum_of(v_full) - x0, sum_of(v_remote) - r0, 100.0 * share,
                           100.0 * stats_pkg::byp_flit()));
    if (rchk_pkg::the_chk != null) begin
      `TB_CHECK(rchk_pkg::the_chk.n_bursts - ckb0 == sum_of(v_used) - b0,
                ("BP05: the checker saw %0d bursts, the sources sent %0d", rchk_pkg::the_chk.n_bursts - ckb0, sum_of(v_used) - b0))
      tb_pkg::info($sformatf("BP05: the checker matched %0d lookahead, link and NI events at their D38 cycles",
                             rchk_pkg::the_chk.n_ev - ck0));
    end
    tb_pkg::cover_bin("BP05 bursts", sum_of(v_used) - b0);
    tb_pkg::cover_goal("BP05 bursts of two or more packets", sum_of(v_multi) - m0);
    tb_pkg::cover_goal("BP05 packets bypassed from a mesh input", sum_of(v_remote) - r0);
    tb_pkg::info($sformatf("BP05: corner cases: a source read a mesh input while a passing burst crossed it in %0d cycles (D38 rule, allowed); %0d bursts arrived on a link the cycle the previous one's last flit crossed; %0d bursts were chosen while the source's previous burst sent its last flit",
                           sum_of(v_rule) - u0, sum_of(v_abut) - a0, sum_of(v_b2b) - z0));
    traffic_defaults();
  endtask
// ---- end tb/mesh/tests_bypass.svh
`endif // NEED_SUPPORT_4
